/* Scenario plans run locally. All operational outputs remain drafts for human review. */
const strategyState={loaded:false,loading:false,view:'overview',source:null,external:false,externalName:'',params:{...STRATEGY.DEFAULTS},
  original:null,case:null,operations:null,comparison:null,baseModel:null,forecast:null,result:null,selected:'balanced',
  taskWeek:0,taskRoute:'',search:'',actuals:{},reviewWeek:1};
const STRATEGY_ROLES={analyst:'Аналітик',operator:'Оператор',legal:'Юрист'};
function selectedStrategy(){return strategyState.result.plans.find(p=>p.profile===strategyState.selected);}
function strategyForecast(){
  if(strategyState.external)return PRE.scorePackage(strategyState.baseModel,strategyState.case);
  const m=strategyState.comparison.models.find(m=>m.key===strategyState.source);
  return {...m.current,horizon_months:12,model_id:m.name+' · '+m.artifact_id,synthetic_training:strategyState.comparison.synthetic};
}
function calculateStrategy(){
  const forecast=strategyForecast(),result=STRATEGY.buildPlans(strategyState.case,strategyState.operations,forecast,strategyState.params);
  strategyState.forecast=forecast;strategyState.result=result;
  strategyState.selected=result.recommendation||'balanced';
}
async function renderStrategy(){
  if(!strategyState.loaded){
    $('#tab-strategy').innerHTML='<div class="panel loadscreen">Підготовка прогнозів і операційних статусів…</div>';$('#report-button').disabled=true;
    if(strategyState.loading)return;strategyState.loading=true;
    try{
      const paths=['prepurchase-case.json','strategy-operations.json','model-comparison.json','prepurchase-model.json'];
      const data=await Promise.all(paths.map(async name=>{const r=await fetch(name);if(!r.ok)throw Error('Не вдалося завантажити '+name);return r.json();}));
      [strategyState.case,strategyState.operations,strategyState.comparison,strategyState.baseModel]=data;
      strategyState.original={case:strategyState.case,operations:strategyState.operations};
      strategyState.source=strategyState.comparison.selection_champion;
      const latest=strategyState.case.snapshots.map(s=>s.as_of_date).sort().at(-1);
      strategyState.params.start_date=STRATEGY.addDays(latest,1);calculateStrategy();strategyState.loaded=true;
    }catch(e){$('#tab-strategy').innerHTML=`<div class="error">${esc(e.message)}</div>`;strategyState.loading=false;return;}
    strategyState.loading=false;if(active!=='strategy')return;
  }
  $('#report-button').disabled=false;updateSource();
  const plan=selectedStrategy(),r=strategyState.result;
  $('#tab-strategy').innerHTML=`<div class="notice strategy-warning"><b>Чернетка сценарної стратегії.</b> Прогнози навчені на синтетичних даних. Частка надходжень за 90 днів, ефект дій та строки їхнього впливу — відкриті припущення. План не надсилає повідомлень і не запускає юридичних дій.</div>
    <div class="panel strategy-source"><div><label for="strategy-source">Джерело 12-місячного прогнозу</label><select id="strategy-source" aria-label="Модель для стратегії" ${strategyState.external?'disabled':''}>${strategyState.external?'<option>Базова демонстраційна модель · зовнішній пакет</option>':strategyState.comparison.models.map(m=>`<option value="${esc(m.key)}" ${m.key===strategyState.source?'selected':''}>${esc(m.name)}</option>`).join('')}</select><p>${strategyState.external?'Завантажено: '+esc(strategyState.externalName)+' · модель залишається синтетично навченою.':'Фіксований синтетичний пакет; його статуси згенеровані, а не перевірені юристом.'}</p></div><div class="strategy-period"><b>${esc(plan.start_date)} → ${esc(plan.end_date)}</b><span>90 днів · 13 тижнів · ${num(plan.coverage.total)} договорів</span></div><div class="download-links"><button class="button secondary" data-strategy-action="import">↑ Дані плану</button>${strategyState.external?'<button class="button secondary" data-strategy-action="demo">↺ Демодані</button>':''}<button class="button primary" data-strategy-action="json">↓ План JSON</button></div></div>
    <div class="pre-tabs strategy-tabs">${[['overview','План і сценарії'],['calendar','Календар і завдання'],['review','Контроль тижня'],['assumptions','Припущення й дані']].map(([key,label])=>`<button data-strategy-view="${key}" class="${strategyState.view===key?'selected':''}">${label}</button>`).join('')}<span class="pre-model-id">${esc(plan.plan_id)}</span></div><div id="strategy-body"></div>`;
  if(strategyState.view==='overview')renderStrategyOverview();else if(strategyState.view==='calendar')renderStrategyCalendar();else if(strategyState.view==='review')renderStrategyReview();else renderStrategyAssumptions();
}
function strategyProfileButtons(){return `<div class="strategy-profile-choices">${strategyState.result.plans.map(p=>`<button class="${strategyState.selected===p.profile?'selected':''}" data-strategy-profile="${p.profile}">${esc(p.label)}${strategyState.result.recommendation===p.profile?' · орієнтир':''}</button>`).join('')}</div>`;}
function strategyBudgetNotice(p){
  if(!p.budget.feasible)return `<div class="error"><b>Бюджету недостатньо.</b> Базове обслуговування, команда й прогнозна комісія потребують ${money(p.budget.baseline_cost)} при доступних ${money(p.budget.spend_limit)} після резерву. Дефіцит ${money(p.budget.funding_shortfall)}. Додаткові завдання не заплановані; базові витрати не приховані.</div>`;
  return `<div class="notice"><b>План у межах заданого бюджету.</b> Резерв ${money(p.budget.reserve)} не витрачається і не віднімається від результату як витрата. Без оцінки у плані: ${num(p.coverage.unscored)} договорів, з них ${num(p.coverage.legal_hold)} додатково відкладено до перевірки документів; їх можливі збори та відповідна комісія невідомі. Фінансовий результат охоплює лише оцінену частину, а облік і команда — весь пакет.</div>`;
}
function renderStrategyOverview(){
  const p=selectedStrategy(),r=strategyState.result;
  $('#strategy-body').innerHTML=`<div class="strategy-card-grid">${r.plans.map(s=>`<button class="strategy-card ${s.profile===p.profile?'selected':''}" data-strategy-profile="${s.profile}" aria-pressed="${s.profile===p.profile}"><span>${s.profile===r.recommendation?'ОРІЄНТИР ЗА СЦЕНАРНИМ СТРЕСОМ':'ВАРІАНТ РОЗПОДІЛУ РЕСУРСІВ'}</span><h2>${esc(s.label)}</h2><strong>${signed(s.totals.incremental_npv)}</strong><small>Додатковий PV-результат відносно обліку без нових дій</small><div><b>${num(s.task_count)}</b> завдань · бюджет <b>${money(s.totals.cost)}</b></div><p>Стрес: ${signed(s.totals.stress_incremental_npv)} · ${s.budget.feasible?'бюджет проходить':'дефіцит бюджету'}</p></button>`).join('')}</div>
    ${!r.recommendation?'<div class="notice">За заданими припущеннями немає варіанта з додатним додатковим PV-результатом у стресі в межах бюджету. Це не скасовує необхідності перевірок документів і даних.</div>':''}
    <div class="metrics strategy-metrics">${metric('Сценарні збори за 90 днів',mln(p.totals.gross),'База '+money(p.totals.base_gross)+' + ефект '+money(p.totals.incremental_gross),'emphasis')}${metric('Повний операційний бюджет',money(p.totals.cost),'Команда, облік усіх вимог, дії та комісія')}${metric('Операційний результат',mln(p.totals.net),'До ціни покупки, податків і фінансування')}${metric('Перевірки поза планом',num(p.critical_pending),'Незаплановані перевірки даних / документів')}</div>
    ${strategyBudgetNotice(p)}
    <div class="two-col strategy-overview-grid"><div class="panel table-panel"><div class="panel-heading"><div><h2>Напрями роботи · ${esc(p.label)}</h2><p>Сегментація враховує операційні прапорці. Низька P платежу не є підставою для юридичної дії.</p></div></div><div class="table-wrap"><table><thead><tr><th>Напрям</th><th class="num">Договорів</th><th class="num">У плані</th><th>Підстава / межа</th></tr></thead><tbody>${Object.entries(p.routes).map(([key,v])=>`<tr><td>${esc(STRATEGY.ROUTES[key].label)}</td><td class="num">${num(v.count)}</td><td class="num">${num(v.scheduled)}</td><td>${key==='monitor'?'Облік без завдань контакту':STRATEGY.ROUTES[key].cash?'Після перевірки допустимості та погодження працівником':'Внутрішня перевірка; ефект надходжень не оцінено'}</td></tr>`).join('')}</tbody></table></div></div><div class="panel strategy-budget"><h2>Звідки береться бюджет</h2><table><tbody><tr><td>Виділена команда за весь період</td><td class="num">${money(p.weeks.reduce((s,w)=>s+Object.values(w.staff).reduce((a,b)=>a+b.cost,0),0))}</td></tr><tr><td>IT / координація</td><td class="num">${money(p.params.overhead_week*90/7)}</td></tr><tr><td>Облік усіх ${num(p.coverage.total)} договорів</td><td class="num">${money(p.coverage.total*p.params.servicing_account_week*90/7)}</td></tr><tr><td>Зовнішні витрати завдань</td><td class="num">${money(p.totals.external_cost)}</td></tr><tr><td>Комісія від прогнозних зборів</td><td class="num">${money(p.totals.commission)}</td></tr><tr class="total-row"><td>Разом витрати</td><td class="num">${money(p.totals.cost)}</td></tr><tr><td>Окремий резерв</td><td class="num">${money(p.budget.reserve)}</td></tr><tr><td>Залишок до резерву</td><td class="num">${money(p.budget.free_before_reserve)}</td></tr></tbody></table><p class="fine">Повна вартість виділених годин оплачується навіть при неповному завантаженні. Вартість годин повторно до завдань не додається. Ціна покупки враховується в загальній оцінці проєкту. Після застосування плану витрати його періоду замінюють відповідну частину загального бюджету.</p></div></div>
    <div class="panel strategy-explanation"><h2>Як читати запропонований план</h2><p>Це евристичний розподіл, а не доведений глобальний оптимум. Спочатку розміщуються внутрішні перевірки. Потім — дозволені чернетки дій за сценарним додатковим PV-результатом на годину, з обмеженнями бюджету та місткості. На одного позичальника — не більше одного завдання контакту на тиждень у цьому плані.</p><p>Орієнтир порівняння — найвищий додатковий PV-результат у заданому стресі. Ефект дій не підтверджений причинною моделлю. Непотрапляння у план не означає, що боржник не платитиме або вимога безнадійна.</p><div class="download-links"><button class="button secondary" data-strategy-view="calendar">Календар і завдання →</button><button class="button secondary" data-strategy-view="assumptions">Змінити припущення →</button></div></div>`;
}
function renderStrategyCalendar(){
  const p=selectedStrategy();
  $('#strategy-body').innerHTML=`${strategyProfileButtons()}<div class="panel table-panel"><div class="panel-heading"><div><h2>Календар 13 тижнів</h2><p>Останній тиждень — 6 днів; місткість та постійні витрати пропорційно зменшені. Надходження і витрати дисконтуються на кінець тижня.</p></div><button class="button secondary" data-strategy-action="weekly-csv">↓ Календар CSV</button></div><div class="table-wrap"><table><thead><tr><th>Тиждень / дати</th><th class="num">Завдань</th><th class="num">База зборів</th><th class="num">Ефект дій*</th><th class="num">Витрати</th><th class="num">Чистий потік</th><th>Завантаження, год<br>аналітик / оператор / юрист</th></tr></thead><tbody>${p.weeks.map(w=>`<tr><td><b>${w.week}</b> · ${esc(w.start_date)}<br><small>${esc(w.end_date)}</small></td><td class="num">${w.tasks.length}</td><td class="num">${money(w.base_gross)}</td><td class="num">${money(w.incremental_gross)}</td><td class="num">${money(w.cost)}</td><td class="num">${signed(w.net)}</td><td>${Object.entries(w.staff).map(([role,s])=>`<span title="${STRATEGY_ROLES[role]}">${num(s.used,1)} / ${num(s.capacity,1)}</span>`).join(' · ')}</td></tr>`).join('')}</tbody></table></div><p class="strategy-table-note">* Ефект дій — сценарне припущення. Збори, очікувані без нових дій, збережено окремо; юридичним та інформаційним перевіркам додаткові збори не приписані.</p></div>
    <div class="panel table-panel strategy-task-panel"><div class="panel-heading"><div><h2>Чернетки завдань для команди</h2><p>Кожне завдання потребує перевірки виконавцем. Юрист отримує перевірку документів, а не автоматичне доручення подати позов.</p></div><button class="button primary" data-strategy-action="tasks-csv">↓ Завдання CSV</button></div><div class="toolbar"><input id="strategy-search" type="search" aria-label="Пошук завдання" placeholder="ID договору / позичальника" value="${esc(strategyState.search)}"><select id="strategy-task-week" aria-label="Тиждень завдання"><option value="0">Усі тижні</option>${p.weeks.map(w=>`<option value="${w.week}" ${w.week===strategyState.taskWeek?'selected':''}>Тиждень ${w.week}</option>`).join('')}</select><select id="strategy-task-route" aria-label="Напрям завдання"><option value="">Усі напрями</option>${Object.entries(STRATEGY.ROUTES).filter(([k])=>k!=='monitor').map(([k,v])=>`<option value="${k}" ${k===strategyState.taskRoute?'selected':''}>${esc(v.label)}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Договір / позичальник</th><th>Тиждень / роль</th><th>Завдання</th><th class="num">Години</th><th class="num">Зовнішня витрата</th><th class="num">Додаткові збори*</th><th>Статус</th></tr></thead><tbody id="strategy-task-rows"></tbody></table></div><div class="pager"><span id="strategy-task-count"></span><span>Показано до 30 завдань; експорт містить усі</span></div></div>`;
  renderStrategyTasks();
}
function renderStrategyTasks(){
  const p=selectedStrategy(),tasks=p.weeks.flatMap(w=>w.tasks.map(t=>({...t,week:w.week}))).filter(t=>(!strategyState.taskWeek||t.week===strategyState.taskWeek)&&(!strategyState.taskRoute||t.route===strategyState.taskRoute)&&(!strategyState.search||(t.loan_id+' '+t.borrower_id).toLowerCase().includes(strategyState.search.toLowerCase())));
  $('#strategy-task-rows').innerHTML=tasks.slice(0,30).map(t=>`<tr><td><b>${esc(t.loan_id)}</b><br><small>${esc(t.borrower_id)}</small></td><td>${t.week} · ${STRATEGY_ROLES[t.role]}</td><td>${esc(t.label)}</td><td class="num">${num(t.hours,2)}</td><td class="num">${money(t.external_cost)}</td><td class="num">${STRATEGY.ROUTES[t.route].cash?money(t.incremental_gross):'Не оцінено'}</td><td><span class="badge review">Чернетка</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">За цими умовами завдань немає.</td></tr>';
  $('#strategy-task-count').textContent=num(tasks.length)+' завдань';
}
function renderStrategyReview(){
  const p=selectedStrategy(),week=p.weeks[strategyState.reviewWeek-1],saved=strategyState.actuals[p.plan_id]?.[strategyState.reviewWeek];
  $('#strategy-body').innerHTML=`${strategyProfileButtons()}<div class="notice">Факт вводиться окремо від плану. Він не переписує початковий прогноз, не доводить причинний ефект дій та не запускає перепланування автоматично. Дані зберігаються лише в пам’яті цієї сторінки; для збереження завантажте JSON плану.</div><div class="two-col strategy-review-grid"><div class="panel"><h2>Щотижнева контрольна точка</h2><label class="strategy-label" for="strategy-review-week">Тиждень</label><select id="strategy-review-week" aria-label="Тиждень контролю">${p.weeks.map(w=>`<option value="${w.week}" ${w.week===strategyState.reviewWeek?'selected':''}>${w.week} · ${esc(w.start_date)} — ${esc(w.end_date)}</option>`).join('')}</select><p class="fine">План зборів: <b>${money(week.gross)}</b>; витрат: <b>${money(week.cost)}</b>.</p><div class="strategy-form-grid"><div><label for="strategy-actual-gross">Фактичні збори, ₴</label><input id="strategy-actual-gross" type="number" min="0" step="0.01" value="${saved?.actual_gross??''}" placeholder="Не введено"></div><div><label for="strategy-actual-cost">Фактичні витрати, ₴</label><input id="strategy-actual-cost" type="number" min="0" step="0.01" value="${saved?.actual_cost??''}" placeholder="Не введено"></div></div><button class="button primary" data-strategy-action="review">Зіставити з планом</button><div id="strategy-review-result"></div></div><div class="panel"><h2>Коли переглядати припущення</h2><ol><li>Збори нижчі за ${pct(p.params.review_collection_floor)} тижневого плану.</li><li>Витрати перевищують ${pct(p.params.review_cost_ceiling)} плану.</li><li>З’явилися нові обмеження взаємодії або непідтверджені документи.</li><li>Не вистачає місткості команди чи є незавершені обов’язкові внутрішні перевірки.</li></ol><p class="fine">Після перевірки причин керівник змінює прогноз, операційні статуси або припущення і формує нову версію плану. При зміні параметрів попередня версія не стає фактом нової. Це контроль виконання, а не доказ того, що стратегія спричинила надходження.</p></div></div>`;
  if(saved)showStrategyReview(saved);
}
function showStrategyReview(r){
  const flags={collections_below_plan:'Збори нижчі за контрольний поріг: перевірте причини та прогноз.',costs_above_plan:'Витрати перевищили контрольний поріг: перевірте склад витрат і бюджет.'};
  $('#strategy-review-result').innerHTML=`<div class="notice ${r.review_required?'strategy-review-alert':''}" style="margin-top:18px"><b>${r.review_required?'Потрібен перегляд':'Пороги не порушені'}</b><p>Виконання зборів: ${r.collection_ratio===null?'план нульовий':pct(r.collection_ratio)}; витрати / план: ${r.cost_ratio===null?'план нульовий':pct(r.cost_ratio)}.</p>${r.flags.map(f=>`<p>${flags[f]}</p>`).join('')}<p class="fine">Початковий план ${esc(r.plan_id)} збережено без змін.</p></div>`;
}
const STRATEGY_PARAM_GROUPS=[
  ['Горизонт і гроші',[['start_date','Початок плану','date'],['budget','Ліміт витрат на 90 днів, ₴'],['reserve_share','Резерв, %','percent'],['annual_discount','Ефективна річна ставка, %','percent'],['share_90d','Частка 12-місячних зборів у 90 днях, %','percent'],['commission_rate','Комісія від зборів, %','percent']]],
  ['Місткість і повна вартість команди',[['analyst_hours_week','Аналітик: годин на тиждень'],['operator_hours_week','Оператор: годин на тиждень'],['legal_hours_week','Юрист: годин на тиждень'],['analyst_hour_cost','Аналітик: ₴ за виділену годину'],['operator_hour_cost','Оператор: ₴ за виділену годину'],['legal_hour_cost','Юрист: ₴ за виділену годину'],['overhead_week','IT / координація, ₴ на тиждень'],['servicing_account_week','Облік одного договору, ₴ на тиждень']]],
  ['Непідтверджені припущення ефекту дій',[['support_uplift','Супровід: приріст майбутніх базових зборів, %','percent'],['offer_uplift','Урегулювання: приріст майбутніх базових зборів, %','percent'],['support_lag_days','Супровід: затримка ефекту, днів'],['offer_lag_days','Урегулювання: затримка ефекту, днів']]],
  ['Зовнішня витрата на одне завдання',[['support_external','Супровід, ₴'],['offer_external','Добровільне врегулювання, ₴'],['legal_external','Перевірка документів юристом, ₴'],['data_external','Уточнення даних, ₴'],['permission_external','Перевірка допустимості, ₴']]],
  ['Стрес і контроль',[['stress_baseline_factor','Стрес: частка базових зборів, %','percent'],['stress_uplift_factor','Стрес: частка ефекту дій, %','percent'],['review_collection_floor','Поріг виконання зборів, %','percent'],['review_cost_ceiling','Поріг витрат / план, %','percent']]]
];
function renderStrategyAssumptions(){
  const p=strategyState.params;
  $('#strategy-body').innerHTML=`<div class="notice"><b>Усі величини нижче — припущення плану.</b> Вони не навчені на історії дій. Частка зборів за 90 днів не є ймовірністю платежу за 90 днів. Базові збори беруться з місячної кривої проєкту; ефект починається після кінця тижня завдання та заданої затримки.</div><div class="panel strategy-assumptions"><h2>Параметри сценарного планування</h2><p class="fine">Налаштування застосуються після перерахунку. Кожна версія має власний ID.</p><form id="strategy-params-form">${STRATEGY_PARAM_GROUPS.map(([title,fields])=>`<fieldset><legend>${esc(title)}</legend><div class="strategy-form-grid">${fields.map(([key,label,type])=>`<div><label for="strategy-param-${key}">${esc(label)}</label><input id="strategy-param-${key}" data-strategy-param="${key}" data-strategy-kind="${type||'number'}" type="${type==='date'?'date':'number'}" ${type==='date'?'':'min="0" step="any"'} value="${type==='percent'?num(p[key]*100,4).replace(/\s/g,'').replace(',','.'):p[key]}" required></div>`).join('')}</div></fieldset>`).join('')}<div class="download-links"><button class="button primary" type="submit">Перерахувати три варіанти</button><button class="button secondary" type="button" data-strategy-action="reset">↺ Опорні припущення</button></div></form></div>
  <div class="two-col strategy-method-grid"><div class="panel method-block"><h2>Прозора логіка</h2><ul><li>База 90 днів = надходження єдиної місячної кривої проєкту за календарні дні плану.</li><li>Додаткові збори = майбутня після затримки частина бази × приріст. Загальна сума не перевищує залишку бази вимоги.</li><li>Вимоги з прапорцем перевірки документів відкладаються без грошової оцінки, навіть якщо попередній ML-прогноз існує.</li><li>Ефект перевірок документів, даних і допустимості не оцінено; у бюджеті є їх зовнішня вартість.</li><li>Команда оплачується за всю виділену місткість, навіть якщо вона не завантажена. Додаткова погодинна плата за завдання не нараховується.</li><li>Тривалість завдання в пілоті: супровід — 0,25 год; урегулювання — 0,75 год; документи — 1 год; дані — 0,5 год; допустимість — 0,25 год.</li><li>У всіх трьох варіантах однакова виділена команда. Відрізняються частка використання операторської місткості, охоплення добровільними пропозиціями та поріг вигоди до зовнішньої витрати. Профілі: 45/75/100% операторської місткості; 35/70/100% дозволених пропозицій; мінімум вигоди до витрати 3/1,5/1.</li><li>Відсоток комісії застосовується один раз до всіх прогнозованих зборів. Резерв — обмеження бюджету, не витрата.</li><li>Ціна купленого портфеля, податки та фінансування не включені. Застосований план замінює операційний бюджет свого періоду й додає ефект дій до фінансової моделі один раз.</li></ul></div><div class="panel method-block"><h2>Дані та обмеження взаємодії</h2><p>JSON складається з <code>case</code> (snapshots, payments) та <code>operations.accounts</code>. Для кожного ID: contact_status = allowed / blocked / unknown; rules_verified; active_payment_plan; legal_review_required; updated_at.</p><p>Непідтверджена допустимість означає внутрішню перевірку. Явна заборона за одним договором зупиняє завдання контакту по всіх договорах цього позичальника. Один контактний чернетковий пункт на позичальника за тиждень — внутрішнє обмеження цього планувальника, а не висновок про дотримання закону.</p><p>Виконавець перевіряє чинні правила, історію контактів, згоди та обмеження перед дією. Програма не перевіряє правовий статус автоматично й не встановлює право на судове стягнення.</p><p>Імпорт обробляється локально. Новий пакет оцінюється базовою моделлю v0.3, навченою на синтетичних даних. Зовнішній імпорт не підтверджує придатності для інвестиційних рішень.</p><div class="download-links"><a class="button secondary" href="strategy-input-demo.json" download>↓ Приклад даних плану</a><a class="button secondary" href="demo-source.zip" download>↓ Код і методика</a><button class="button secondary" data-strategy-action="import">↑ Свій пакет</button></div></div></div>`;
}
function strategyMemo(){
  if(!strategyState.loaded)return '<article class="memo"><p>План ще завантажується.</p></article>';
  const p=selectedStrategy();
  return `<article class="memo"><div class="memo-label">ЧЕРНЕТКА СЦЕНАРНОЇ СТРАТЕГІЇ · 90 ДНІВ</div><h2>${esc(p.label)} · ${esc(p.start_date)} — ${esc(p.end_date)}</h2><p>Версія ${esc(p.plan_id)}. Джерело: ${esc(strategyState.result.source_model)}. Модель навчена на синтетичних даних; ефект дій і строки — сценарні припущення.</p><table><tbody><tr><td>Договорів / без оцінки в плані</td><td>${num(p.coverage.total)} / ${num(p.coverage.unscored)}</td></tr><tr><td>Базові збори за 90 днів</td><td>${money(p.totals.base_gross)}</td></tr><tr><td>Сценарні додаткові збори</td><td>${money(p.totals.incremental_gross)}</td></tr><tr><td>Збори разом / витрати</td><td>${money(p.totals.gross)} / ${money(p.totals.cost)}</td></tr><tr><td>Операційний результат до ціни покупки</td><td>${money(p.totals.net)}</td></tr><tr><td>Додатковий PV-результат / у стресі</td><td>${signed(p.totals.incremental_npv)} / ${signed(p.totals.stress_incremental_npv)}</td></tr><tr><td>Ліміт / окремий резерв</td><td>${money(p.params.budget)} / ${money(p.budget.reserve)}</td></tr><tr><td>Завдань / внутрішніх перевірок поза планом</td><td>${p.task_count} / ${p.critical_pending}</td></tr></tbody></table><h3>Напрями</h3><ul>${Object.entries(p.routes).map(([k,v])=>`<li>${esc(STRATEGY.ROUTES[k].label)}: ${v.count} договорів; у плані ${v.scheduled}.</li>`).join('')}</ul><h3>Календар і контроль</h3><table><thead><tr><th>Тиждень</th><th>Завдань</th><th>Збори</th><th>Витрати</th></tr></thead><tbody>${p.weeks.map(w=>`<tr><td>${w.week} · ${esc(w.start_date)}</td><td>${w.tasks.length}</td><td>${money(w.gross)}</td><td>${money(w.cost)}</td></tr>`).join('')}</tbody></table><p>Щотижневий перегляд при зборах нижче ${pct(p.params.review_collection_floor)} плану або витратах вище ${pct(p.params.review_cost_ceiling)}. Факт зберігається окремо, не переписуючи початковий план.</p><h3>Обмеження</h3><p>Статус — чернетка для перевірки керівником. ${p.budget.feasible?'Бюджет проходить за введеними припущеннями.':'Є дефіцит бюджету: '+money(p.budget.funding_shortfall)+'.'} Це евристичний розподіл, не доведений оптимум. Дії потребують перевірки допустимості; юридична задача — лише перевірка документів. Повідомлення і позови автоматично не надсилаються. Прибутковість покупки, податки та фінансування не оцінені. Усі припущення й завдання доступні у JSON плану.</p><small>Sergey Golubev · NPL Investment Lab</small></article>`;
}
function strategyCSV(name,fields,rows){
  const cell=v=>{if(v===null||v===undefined)return '';let s=String(v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
  download(name,'\uFEFF'+[fields.join(','),...rows.map(r=>fields.map(k=>cell(r[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8');
}
function exportStrategy(action){
  const p=selectedStrategy();
  if(action==='json'){
    const data={schema_version:1,source_model:strategyState.result.source_model,synthetic_training:strategyState.result.synthetic_training,
      synthetic_data:strategyState.result.synthetic_data,source_fingerprint:strategyState.result.source_fingerprint,
      frozen_plan:p,actuals:strategyState.actuals[p.plan_id]||{},limitations:['Scenario action effects, not causal estimates','Draft for human review','Purchase price, tax and financing excluded']};
    download('npl-'+p.plan_id+'.json',JSON.stringify(data,null,2),'application/json');
  }else if(action==='weekly-csv'){
    strategyCSV('npl-strategy-weeks.csv',['plan_id','week','start_date','end_date','days','base_gross','incremental_gross','gross','fixed_cost','external_cost','commission','cost','net','analyst_hours','operator_hours','legal_hours'],p.weeks.map(w=>({...w,plan_id:p.plan_id,analyst_hours:w.staff.analyst.used,operator_hours:w.staff.operator.used,legal_hours:w.staff.legal.used})));
  }else{
    strategyCSV('npl-strategy-tasks.csv',['plan_id','week','loan_id','borrower_id','route','label','role','hours','external_cost','incremental_gross','status','reason'],p.weeks.flatMap(w=>w.tasks.map(t=>({...t,plan_id:p.plan_id,week:w.week}))));
  }
  toast('План '+p.plan_id+' експортовано.');
}
document.addEventListener('click',e=>{
  const view=e.target.closest('[data-strategy-view]');if(view){strategyState.view=view.dataset.strategyView;renderStrategy();}
  const profile=e.target.closest('[data-strategy-profile]');if(profile){strategyState.selected=profile.dataset.strategyProfile;renderStrategy();}
  const action=e.target.closest('[data-strategy-action]')?.dataset.strategyAction;if(!action)return;
  if(['json','weekly-csv','tasks-csv'].includes(action))exportStrategy(action);
  if(action==='import')$('#strategy-input').click();
  if(action==='demo'){strategyState.case=strategyState.original.case;strategyState.operations=strategyState.original.operations;strategyState.external=false;strategyState.source=strategyState.comparison.selection_champion;strategyState.params={...STRATEGY.DEFAULTS};calculateStrategy();error('');renderStrategy();}
  if(action==='reset'){strategyState.params={...STRATEGY.DEFAULTS,start_date:STRATEGY.addDays(strategyState.case.snapshots.map(s=>s.as_of_date).sort().at(-1),1)};calculateStrategy();error('');renderStrategy();}
  if(action==='review')try{
    const gross=$('#strategy-actual-gross').value,cost=$('#strategy-actual-cost').value;if(gross===''||cost==='')throw Error('Введіть обидва фактичні значення.');
    const p=selectedStrategy(),r=STRATEGY.reviewWeek(p,strategyState.reviewWeek,Number(gross),Number(cost));
    (strategyState.actuals[p.plan_id]||={})[strategyState.reviewWeek]=r;error('');showStrategyReview(r);
  }catch(err){error(err.message);}
});
document.addEventListener('submit',e=>{
  if(e.target.id!=='strategy-params-form')return;e.preventDefault();
  try{
    const params={...strategyState.params};e.target.querySelectorAll('[data-strategy-param]').forEach(el=>{
      if(el.value==='')throw Error('Заповніть усі параметри.');
      params[el.dataset.strategyParam]=el.dataset.strategyKind==='date'?el.value:Number(el.value)/(el.dataset.strategyKind==='percent'?100:1);
    });
    const normalized=STRATEGY.normalizeParams(params),forecast=strategyForecast(),result=STRATEGY.buildPlans(strategyState.case,strategyState.operations,forecast,normalized);
    strategyState.params=normalized;strategyState.forecast=forecast;strategyState.result=result;strategyState.selected=result.recommendation||'balanced';strategyState.view='overview';error('');renderStrategy();toast('Сформовано нову версію плану.');
  }catch(err){error('План не змінено: '+err.message);}
});
document.addEventListener('input',e=>{if(e.target.id==='strategy-search'){strategyState.search=e.target.value;renderStrategyTasks();}});
document.addEventListener('change',async e=>{
  if(e.target.id==='strategy-source'){strategyState.source=e.target.value;calculateStrategy();error('');renderStrategy();}
  if(e.target.id==='strategy-task-week'){strategyState.taskWeek=Number(e.target.value);renderStrategyTasks();}
  if(e.target.id==='strategy-task-route'){strategyState.taskRoute=e.target.value;renderStrategyTasks();}
  if(e.target.id==='strategy-review-week'){strategyState.reviewWeek=Number(e.target.value);renderStrategyReview();}
  if(e.target.id!=='strategy-input')return;
  const file=e.target.files[0];if(!file)return;
  try{
    if(file.size>20*1024*1024)throw Error('Ліміт JSON — 20 МБ.');const data=JSON.parse(await file.text());
    const forecast=PRE.scorePackage(strategyState.baseModel,data.case),latest=data.case.snapshots.map(s=>s.as_of_date).sort().at(-1),params={...strategyState.params,start_date:STRATEGY.addDays(latest,1)};
    const result=STRATEGY.buildPlans(data.case,data.operations,forecast,params);
    strategyState.case=data.case;strategyState.operations=data.operations;strategyState.params=params;strategyState.forecast=forecast;strategyState.result=result;
    strategyState.external=true;strategyState.externalName=file.name;strategyState.selected=result.recommendation||'balanced';strategyState.view='overview';error('');renderStrategy();toast('Пакет перевірено локально; використано базову демонстраційну модель.');
  }catch(err){error('Пакет не завантажено: '+err.message);}finally{e.target.value='';}
});
